UPDATE materias SET descripcion = 'En esta materia se estudiarán los conceptos esenciales de la informática, el funcionamiento de las computadoras, el hardware, el software y los sistemas operativos. Se introducirán la lógica computacional, los algoritmos y los fundamentos del desarrollo de software para comprender cómo funcionan y se crean las aplicaciones.', programa = 'En esta materia se estudiarán los conceptos esenciales de la informática, el funcionamiento de las computadoras, el hardware, el software y los sistemas operativos. Se introducirán la lógica computacional, los algoritmos y los fundamentos del desarrollo de software para comprender cómo funcionan y se crean las aplicaciones.' WHERE nombre = 'Fundamentos de Infraestructura y Software';
UPDATE materias SET descripcion = 'En esta materia se integrarán ciencia, tecnología, ingeniería, arte y matemáticas mediante actividades prácticas y proyectos. Se desarrollarán la creatividad, el pensamiento lógico y la resolución de problemas a través de experiencias como programación, robótica, diseño y construcción de prototipos.', programa = 'En esta materia se integrarán ciencia, tecnología, ingeniería, arte y matemáticas mediante actividades prácticas y proyectos. Se desarrollarán la creatividad, el pensamiento lógico y la resolución de problemas a través de experiencias como programación, robótica, diseño y construcción de prototipos.' WHERE nombre = 'Fundamentos STEAM';
UPDATE materias SET descripcion = 'En esta materia se desarrollarán habilidades de lectura, escritura, comprensión y comunicación en inglés. Se trabajará con vocabulario general y tecnológico, documentación informática, instrucciones y términos utilizados en programación, redes y sistemas operativos.', programa = 'En esta materia se desarrollarán habilidades de lectura, escritura, comprensión y comunicación en inglés. Se trabajará con vocabulario general y tecnológico, documentación informática, instrucciones y términos utilizados en programación, redes y sistemas operativos.' WHERE nombre = 'Inglés';
UPDATE materias SET descripcion = 'En esta materia se aprenderán los conceptos básicos de Linux y el uso de la terminal. Se trabajará con comandos, archivos, directorios, usuarios, permisos, procesos e instalación de programas. También se introducirán la administración básica del sistema, los conceptos de seguridad y la creación de scripts de Bash para automatizar tareas.', programa = 'En esta materia se aprenderán los conceptos básicos de Linux y el uso de la terminal. Se trabajará con comandos, archivos, directorios, usuarios, permisos, procesos e instalación de programas. También se introducirán la administración básica del sistema, los conceptos de seguridad y la creación de scripts de Bash para automatizar tareas.' WHERE nombre = 'Introducción a Linux';
UPDATE materias SET descripcion = 'En esta materia se aprenderán los fundamentos de la programación para resolver problemas mediante código. Se trabajará con variables, tipos de datos, operadores, condiciones, bucles, funciones y algoritmos. Se desarrollará el pensamiento lógico mediante ejercicios prácticos y pequeños programas.', programa = 'En esta materia se aprenderán los fundamentos de la programación para resolver problemas mediante código. Se trabajará con variables, tipos de datos, operadores, condiciones, bucles, funciones y algoritmos. Se desarrollará el pensamiento lógico mediante ejercicios prácticos y pequeños programas.' WHERE nombre = 'Introducción a Lenguaje';
UPDATE materias SET descripcion = 'En esta materia se estudiarán los fundamentos de las redes de computadoras, los modelos de referencia y los protocolos de comunicación. Se abordarán conceptos como direccionamiento IP, topologías, dispositivos de red y seguridad básica.', programa = 'En esta materia se estudiarán los fundamentos de las redes de computadoras, los modelos de referencia y los protocolos de comunicación. Se abordarán conceptos como direccionamiento IP, topologías, dispositivos de red y seguridad básica.' WHERE nombre = 'Introducción a Redes';
UPDATE materias SET descripcion = 'En esta materia se estudiarán diferentes soluciones tecnológicas aplicadas a la construcción. Se analizarán sistemas constructivos tradicionales y modernos, materiales, herramientas, técnicas de ejecución y nuevas tecnologías. Se compararán sus ventajas, desventajas, costos, eficiencia y sostenibilidad para seleccionar las alternativas más adecuadas según las necesidades de cada proyecto.', programa = 'En esta materia se estudiarán diferentes soluciones tecnológicas aplicadas a la construcción. Se analizarán sistemas constructivos tradicionales y modernos, materiales, herramientas, técnicas de ejecución y nuevas tecnologías. Se compararán sus ventajas, desventajas, costos, eficiencia y sostenibilidad para seleccionar las alternativas más adecuadas según las necesidades de cada proyecto.' WHERE nombre = 'Alternativas tecnológicas';
UPDATE materias SET descripcion = 'En esta materia se aprenderán los procedimientos básicos para ejecutar trabajos de construcción en obra. Se estudiarán la preparación del terreno, la organización del espacio de trabajo, el uso de herramientas, la interpretación de indicaciones técnicas y la ejecución de tareas constructivas. Se trabajará con materiales, procedimientos y controles básicos de calidad, aplicando las normas de seguridad correspondientes.', programa = 'En esta materia se aprenderán los procedimientos básicos para ejecutar trabajos de construcción en obra. Se estudiarán la preparación del terreno, la organización del espacio de trabajo, el uso de herramientas, la interpretación de indicaciones técnicas y la ejecución de tareas constructivas. Se trabajará con materiales, procedimientos y controles básicos de calidad, aplicando las normas de seguridad correspondientes.' WHERE nombre = 'Ejecución de obra A';
UPDATE materias SET descripcion = 'En esta materia se profundizarán los conocimientos y las habilidades prácticas necesarios para realizar y supervisar trabajos de construcción. Se abordarán procedimientos constructivos, coordinación de tareas, uso adecuado de herramientas y equipos, control de calidad y cumplimiento de normas de seguridad.', programa = 'En esta materia se profundizarán los conocimientos y las habilidades prácticas necesarios para realizar y supervisar trabajos de construcción. Se abordarán procedimientos constructivos, coordinación de tareas, uso adecuado de herramientas y equipos, control de calidad y cumplimiento de normas de seguridad.' WHERE nombre = 'Ejecución de obra B';
UPDATE materias SET descripcion = 'En esta materia se estudiarán los fundamentos de la planificación, organización y gestión de proyectos de construcción. Se aprenderá a organizar actividades, establecer plazos, distribuir recursos y estimar costos. También se introducirán herramientas de programación de obra, seguimiento de tareas, control de avances y coordinación de los recursos humanos y materiales necesarios para desarrollar un proyecto.', programa = 'En esta materia se estudiarán los fundamentos de la planificación, organización y gestión de proyectos de construcción. Se aprenderá a organizar actividades, establecer plazos, distribuir recursos y estimar costos. También se introducirán herramientas de programación de obra, seguimiento de tareas, control de avances y coordinación de los recursos humanos y materiales necesarios para desarrollar un proyecto.' WHERE nombre = 'Programación y gestión 1';
UPDATE materias SET descripcion = 'En esta materia se aprenderán los principios del dibujo técnico aplicados a la construcción. Se trabajará con escalas, cotas, tipos de líneas, simbología, vistas, cortes y representación de elementos constructivos. También se desarrollará la capacidad de interpretar planos y realizar representaciones gráficas que permitan comunicar las características y dimensiones de un proyecto de construcción.', programa = 'En esta materia se aprenderán los principios del dibujo técnico aplicados a la construcción. Se trabajará con escalas, cotas, tipos de líneas, simbología, vistas, cortes y representación de elementos constructivos. También se desarrollará la capacidad de interpretar planos y realizar representaciones gráficas que permitan comunicar las características y dimensiones de un proyecto de construcción.' WHERE nombre = 'Representación técnica 1';
UPDATE materias SET descripcion = 'En esta materia se estudiarán los principios de seguridad y prevención de riesgos laborales en la construcción. Se identificarán peligros habituales en una obra, se analizarán medidas preventivas y se aprenderá a utilizar correctamente los equipos de protección personal. También se abordarán la señalización, el orden y la limpieza, el trabajo seguro con herramientas y maquinaria, y los procedimientos básicos de actuación ante emergencias.', programa = 'En esta materia se estudiarán los principios de seguridad y prevención de riesgos laborales en la construcción. Se identificarán peligros habituales en una obra, se analizarán medidas preventivas y se aprenderá a utilizar correctamente los equipos de protección personal. También se abordarán la señalización, el orden y la limpieza, el trabajo seguro con herramientas y maquinaria, y los procedimientos básicos de actuación ante emergencias.' WHERE nombre = 'Seguridad';
UPDATE materias SET descripcion = 'En esta materia se estudiarán las propiedades, características y aplicaciones de los materiales utilizados en la construcción, como cementos, hormigones, morteros, cerámicos, metales, madera y otros productos. Se analizarán los procesos de fabricación, transporte, preparación, colocación y utilización de estos materiales, así como su comportamiento, durabilidad, calidad y adecuación a diferentes sistemas constructivos.', programa = 'En esta materia se estudiarán las propiedades, características y aplicaciones de los materiales utilizados en la construcción, como cementos, hormigones, morteros, cerámicos, metales, madera y otros productos. Se analizarán los procesos de fabricación, transporte, preparación, colocación y utilización de estos materiales, así como su comportamiento, durabilidad, calidad y adecuación a diferentes sistemas constructivos.' WHERE nombre = 'Tecnología de los procesos y materiales';
UPDATE materias SET descripcion = 'En esta materia se aprenderán los fundamentos de la topografía y los métodos utilizados para medir y representar terrenos. Se trabajará con distancias, ángulos, cotas, desniveles, pendientes y perfiles del terreno. También se estudiará el uso de instrumentos topográficos, la interpretación de planos y la realización de mediciones necesarias para replantear construcciones y determinar la ubicación y las dimensiones de los elementos de una obra.', programa = 'En esta materia se aprenderán los fundamentos de la topografía y los métodos utilizados para medir y representar terrenos. Se trabajará con distancias, ángulos, cotas, desniveles, pendientes y perfiles del terreno. También se estudiará el uso de instrumentos topográficos, la interpretación de planos y la realización de mediciones necesarias para replantear construcciones y determinar la ubicación y las dimensiones de los elementos de una obra.' WHERE nombre = 'Topografía';

    INSERT INTO tareas (titulo, descripcion, materia_id, asignada_por, fecha_publicacion, fecha_entrega, estado, ponderacion, acepta_tardias)
    VALUES ('Tarea 1 — Modelo OSI y TCP/IP', 'Investigar las capas del modelo OSI y compararlas con el modelo TCP/IP. Explicar la función de cada capa y dar ejemplos de protocolos.', 3, 86, NOW(), DATE_ADD(NOW(), INTERVAL 7 DAY), 'publicada', 10, 1);
    

    INSERT INTO tareas (titulo, descripcion, materia_id, asignada_por, fecha_publicacion, fecha_entrega, estado, ponderacion, acepta_tardias)
    VALUES ('Tarea 2 — Crear una red LAN', 'Diseñar una red con tres computadoras y un switch utilizando Packet Tracer. Asignar direcciones IP y comprobar la comunicación entre los equipos.', 3, 86, NOW(), DATE_ADD(NOW(), INTERVAL 7 DAY), 'publicada', 15, 1);
    

    INSERT INTO tareas (titulo, descripcion, materia_id, asignada_por, fecha_publicacion, fecha_entrega, estado, ponderacion, acepta_tardias)
    VALUES ('Tarea 3 — Comandos de diagnóstico de red', 'Utilizar comandos como ipconfig, ping, tracert, nslookup y netstat para consultar la configuración de red y diagnosticar problemas básicos de conectividad.', 3, 86, NOW(), DATE_ADD(NOW(), INTERVAL 7 DAY), 'publicada', 10, 1);
    

    INSERT INTO tareas (titulo, descripcion, materia_id, asignada_por, fecha_publicacion, fecha_entrega, estado, ponderacion, acepta_tardias)
    VALUES ('Tarea 4 — Cableado estructurado', 'Investigar los cables Ethernet, conectores RJ45 y normas de cableado T568A y T568B. Dibujar el orden de los conductores y explicar cuándo se utiliza cada norma.', 3, 86, NOW(), DATE_ADD(NOW(), INTERVAL 7 DAY), 'publicada', 10, 1);
    

    INSERT INTO tareas (titulo, descripcion, materia_id, asignada_por, fecha_publicacion, fecha_entrega, estado, ponderacion, acepta_tardias)
    VALUES ('Tarea 5 — Seguridad básica de redes', 'Explicar qué hacen un firewall, una contraseña segura, el cifrado Wi-Fi y las actualizaciones. Proponer medidas para proteger una red doméstica o educativa.', 3, 86, NOW(), DATE_ADD(NOW(), INTERVAL 7 DAY), 'publicada', 10, 1);
    
